# Build target song_ids from the old songs file via spotify.search_songs

from collections import defaultdict

content = file_info.get('content','')
lines = [ln.strip() for ln in content.splitlines() if ln.strip()]
old_entries = []
for ln in lines:
    if ln.startswith('#'):
        continue
    if ln.startswith('- '):
        ln = ln[2:].strip()
    elif ln.startswith('-'):
        ln = ln[1:].strip()
    if ln:
        old_entries.append(ln)

print('old_entries_count', len(old_entries))

parsed_entries = []
for e in old_entries:
    if ' by ' in e:
        title, artists = e.split(' by ', 1)
        title = title.strip()
        artists = artists.strip()
        artist_list = [a.strip() for a in artists.split(',') if a.strip()]
    else:
        title = e.strip()
        artist_list = []
    parsed_entries.append({'title': title, 'artist_list': artist_list, 'raw': e})

print('parsed_entries', parsed_entries)

spotify_search_page_limit = 20

def norm(s):
    return ' '.join(s.lower().strip().split())

target_song_ids = set()
entry_to_matched_ids = defaultdict(list)

for i, pe in enumerate(parsed_entries):
    title = pe['title']
    artist_list = pe['artist_list']

    query = (title + ' ' + ' '.join(artist_list)).strip()
    print('\nENTRY', i, 'query=', query)

    matched_exact = []
    matched_title_only = []

    page_index = 0
    while True:
        res = apis.spotify.search_songs(query=query, page_index=page_index, page_limit=spotify_search_page_limit)
        if not res:
            break
        for song in res:
            stitle = song.get('title','')
            sartist_names = [a.get('name','') for a in song.get('artists',[])]
            if norm(stitle) == norm(title):
                if artist_list:
                    needed = [norm(a) for a in artist_list]
                    sartist_norm_set = set(norm(a) for a in sartist_names)
                    if all(n in sartist_norm_set for n in needed):
                        matched_exact.append(song)
                    else:
                        matched_title_only.append(song)
                else:
                    matched_exact.append(song)
        page_index += 1

    # de-dup by song_id
    def dedup_songs(songs):
        seen=set(); out=[]
        for s in songs:
            sid=s.get('song_id') or s.get('id')
            if sid is None: 
                continue
            if sid not in seen:
                seen.add(sid)
                out.append(s)
        return out

    matched_exact = dedup_songs(matched_exact)
    matched_title_only = dedup_songs(matched_title_only)

    if matched_exact:
        chosen = matched_exact
        reason = 'title+artists'
    elif matched_title_only:
        chosen = matched_title_only
        reason = 'title_only'
    else:
        chosen = []
        reason = 'no_match'

    chosen_ids = [s['song_id'] for s in chosen]
    print('matched_exact_count', len(matched_exact), 'matched_title_only_count', len(matched_title_only), 'chosen_reason', reason, 'chosen_ids', chosen_ids)

    for sid in chosen_ids:
        target_song_ids.add(sid)
        entry_to_matched_ids[i].append(sid)

print('\nTARGET_SONG_IDS_COUNT', len(target_song_ids))
print('TARGET_SONG_IDS_SAMPLE', sorted(list(target_song_ids))[:50])
